export enum LeaveRequestStatus {
  DRAFT = 'DRAFT',
  SUBMITTED = 'SUBMITTED',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED',
  CANCELLED = 'CANCELLED',
}

export enum LeaveType {
  annual = 'annual',
  sick = 'sick',
  emergency = 'emergency',
  unpaid = 'unpaid',
  maternity = 'maternity',
  paternity = 'paternity',
}

export enum BalanceStatus {
  ACTIVE = 'ACTIVE',
  EXHAUSTED = 'EXHAUSTED',
  CLOSED = 'CLOSED',
}

export enum EmploymentStatus {
  ACTIVE = 'ACTIVE',
  INACTIVE = 'INACTIVE',
  TERMINATED = 'TERMINATED',
}

export interface BaseEntity {
  id: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface AuditRecord {
  id: string;
  entityType: string;
  entityId: string;
  action: string;
  oldValues: Record<string, unknown> | null;
  newValues: Record<string, unknown> | null;
  performedBy: string;
  performedAt: Date;
  ipAddress: string | undefined;
  userAgent: string | undefined;
  createdAt: Date;
}

import { AuditRecord } from './audit.model';

export interface IAuditRepository {
  create(record: AuditRecord): Promise<AuditRecord>;
  findByEntity(entityType: string, entityId: string): Promise<AuditRecord[]>;
}

import { AuditRecord } from './audit.model';

export interface IAuditService {
  record(params: {
    entityType: string;
    entityId: string;
    action: string;
    oldValues?: Record<string, unknown> | null;
    newValues?: Record<string, unknown> | null;
    performedBy: string;
    ipAddress?: string;
    userAgent?: string;
  }): Promise<AuditRecord>;
}
